// Differential fuzz: our BIP-39/BIP-32 HD derivation vs the TronWeb gold
// standard (`TronWeb.fromMnemonic`), over a deterministic corpus
// (test/fixtures/sig/fuzz.json, generated by scripts/gen-sig-fuzz.mjs). Each
// case pins the derived Base58 address + uncompressed public key across TRON
// paths (coin type 195); we diff our stack. No secret is embedded — phrases
// come from obviously-trivial entropy and only public values are pinned.
import { entropyToMnemonic } from '@scure/bip39'
import { wordlist } from '@scure/bip39/wordlists/english'
import { describe, expect, test } from 'vitest'

import {
  loadSigFuzzFixtures,
  type SigFuzzHdFixture,
} from '../fixtures/sig/loader.js'
import type { Hex } from '../../src/types/misc.js'
import { hexToBytes } from '../../src/utils/encoding/toBytes.js'
import { mnemonicToAccount } from '../../src/accounts/mnemonicToAccount.js'

const { meta, hd } = loadSigFuzzFixtures()

describe('HD account fuzz (differential vs TronWeb)', () => {
  test('the corpus sweeps trivial entropies across TRON paths', () => {
    expect(hd.length).toBe(meta.hdCount)
    expect(hd.length).toBeGreaterThanOrEqual(30)
  })

  test.each(
    hd.map((h) => [h.name, h] as const),
  )('hd %s', (_name, fixture: SigFuzzHdFixture) => {
    const mnemonic = entropyToMnemonic(
      hexToBytes(`0x${fixture.entropyHex}` as Hex),
      wordlist,
    )
    const account = mnemonicToAccount(mnemonic, {
      path: fixture.path as `m/44'/195'/${string}`,
      passphrase: fixture.passphrase,
    })
    expect(account.address).toBe(fixture.address)
    expect(account.publicKey).toBe(fixture.publicKey)
  })
})
